def count_Odd_Squares(n, m):
    """Write a python function to find number of elements with odd factors in a given range."""
    if n > m:
        return 0
    if m < 0:
        return 0
    low = max(n, 0)
    low_int = math.ceil(low)
    high_int = math.floor(m)
    if low_int > high_int:
        return 0
    start = math.isqrt(low_int)
    if start * start < low_int:
        start += 1
    end = math.isqrt(high_int)
    result = end - start + 1
    return result if result > 0 else 0
